export default "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Bark 推送游乐场</title>\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script src=\"https://unpkg.com/vue@3/dist/vue.global.prod.js\"></script>\n<style>\n  [v-cloak] { display: none; }\n  html { color-scheme: dark; }\n  body { font-family: ui-sans-serif, system-ui, \"Segoe UI\", \"Microsoft YaHei\", sans-serif; }\n  .inp {\n    width: 100%; border-radius: .6rem; border: 1px solid #1e293b;\n    background: #0b1220; padding: .55rem .7rem; font-size: .875rem;\n    color: #e2e8f0; outline: none; transition: border-color .15s, box-shadow .15s;\n  }\n  textarea.inp { resize: vertical; min-height: 4rem; line-height: 1.5; }\n  .inp::placeholder { color: #475569; }\n  .inp:focus { border-color: #f59e0b; box-shadow: 0 0 0 3px rgba(245, 158, 11, .14); }\n  select.mini { width: auto; min-width: 5.2rem; padding: .25rem 1.5rem .25rem .5rem; font-size: .72rem; }\n  .lbl { font-size: .7rem; color: #64748b; }\n  .card { border-radius: 1rem; border: 1px solid #1e293b; background: rgba(15, 23, 42, .6); padding: 1.1rem; }\n  .scenario {\n    display: flex; width: 100%; align-items: center; gap: .65rem; text-align: left;\n    border: 1px solid #1e293b; border-radius: .8rem; background: #0b1220;\n    padding: .6rem .7rem; transition: border-color .15s, background .15s, box-shadow .15s;\n  }\n  .scenario:hover { border-color: #475569; background: #0f172a; }\n  .scenario.active { border-color: #f59e0b; background: rgba(245, 158, 11, .08); box-shadow: 0 0 0 3px rgba(245, 158, 11, .07); }\n  .tagchip {\n    display: inline-block; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n    border: 1px solid #1e293b; border-radius: 999px; background: #0b1220;\n    padding: .08rem .5rem; font-size: 10px; font-family: ui-monospace, Consolas, monospace; color: #94a3b8;\n  }\n  .clamp4 { display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical; overflow: hidden; }\n  .btn { border-radius: .6rem; padding: .45rem .8rem; font-size: .75rem; font-weight: 600; transition: background .15s, color .15s; }\n  .btn-primary { background: #f59e0b; color: #0f172a; }\n  .btn-primary:hover { background: #fbbf24; }\n  .btn-primary:disabled { opacity: .45; cursor: not-allowed; }\n  .btn-ghost { border: 1px solid #334155; color: #cbd5e1; background: transparent; }\n  .btn-ghost:hover { border-color: #64748b; color: #f8fafc; }\n  .hint { font-size: .7rem; line-height: 1.5; color: #64748b; }\n  pre { font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: .7rem; line-height: 1.55; white-space: pre-wrap; word-break: break-all; }\n  details > summary { cursor: pointer; font-size: .72rem; color: #94a3b8; user-select: none; }\n  details[open] > summary { margin-bottom: .4rem; }\n  .toast { position: fixed; left: 50%; bottom: 1.5rem; transform: translateX(-50%); z-index: 60; }\n  input[type=\"checkbox\"] { accent-color: #f59e0b; }\n  .modal { position: fixed; inset: 0; z-index: 70; display: grid; place-items: center; background: rgba(2, 6, 23, .8); backdrop-filter: blur(4px); }\n</style>\n</head>\n<body class=\"bg-slate-950 text-slate-200 antialiased\">\n<div id=\"app\" v-cloak class=\"min-h-screen\">\n\n  <header class=\"sticky top-0 z-30 border-b border-slate-800/80 bg-slate-950/90 backdrop-blur\">\n    <div class=\"mx-auto flex max-w-7xl flex-wrap items-center gap-3 px-4 py-3\">\n      <div class=\"grid h-10 w-10 place-items-center rounded-xl bg-amber-500 font-black text-slate-950\">B</div>\n      <div class=\"min-w-0\">\n        <h1 class=\"text-base font-semibold text-slate-100\">Bark 推送游乐场</h1>\n        <p class=\"truncate text-xs text-slate-500\">\n          点场景 → 点发送 · {{ cfg.server || '—' }} · 设备\n          <span class=\"font-mono text-amber-500/80\">{{ cfg.device_key_masked || '未配置' }}</span>\n        </p>\n      </div>\n      <div class=\"ml-auto flex items-center gap-2\">\n        <button v-if=\"cfg.auth_required\" class=\"btn btn-ghost !px-2.5 !py-1.5\" @click=\"openKeyDialog\">\n          {{ token ? '已认证' : '填 KEY' }}\n        </button>\n        <label class=\"flex cursor-pointer items-center gap-1.5 rounded-lg border px-3 py-2 text-xs transition\"\n               :class=\"encrypt ? 'border-amber-500/50 bg-amber-500/10 text-amber-400' : 'border-slate-700 text-slate-400'\">\n          <input type=\"checkbox\" v-model=\"encrypt\" class=\"h-4 w-4\">\n          加密\n        </label>\n        <button class=\"btn btn-primary px-5 py-2.5 text-sm\" :disabled=\"sending || !selected\" @click=\"send\">\n          {{ sending ? '发送中…' : '发送' }}<span class=\"hidden sm:inline\"> · {{ selected ? selected.label : '选场景' }}</span>\n        </button>\n      </div>\n    </div>\n\n    <div v-if=\"encrypt\" class=\"border-t border-slate-800/70 bg-slate-900/50\">\n      <div class=\"mx-auto flex max-w-7xl flex-wrap items-center gap-2 px-4 py-2 text-xs\">\n        <span class=\"lbl\">算法</span>\n        <select class=\"inp mini\" v-model=\"algorithm\">\n          <option v-for=\"a in cfg.algorithms\" :key=\"a\" :value=\"a\">{{ a.toUpperCase() }}</option>\n        </select>\n        <span class=\"lbl\">模式</span>\n        <select class=\"inp mini\" v-model=\"mode\">\n          <option v-for=\"m in cfg.modes\" :key=\"m\" :value=\"m\">{{ m.toUpperCase() }}</option>\n        </select>\n        <code class=\"rounded-md border border-slate-800 bg-slate-950/80 px-2 py-1 font-mono text-amber-400\">{{ currentKey }}</code>\n        <button class=\"btn btn-ghost !px-2.5 !py-1\" @click=\"copy(currentKey, '密钥')\">复制 KEY</button>\n        <button class=\"btn btn-ghost !px-2.5 !py-1\" @click=\"regenerate\">换一个</button>\n        <span class=\"text-slate-500\">App 首页 →「推送加密」填相同算法 / 模式 / KEY</span>\n      </div>\n    </div>\n  </header>\n\n  <main class=\"mx-auto grid max-w-7xl gap-6 px-4 py-6 lg:grid-cols-[minmax(0,1fr)_360px]\">\n\n    <div class=\"space-y-4\">\n      <section v-for=\"group in scenarioGroups\" :key=\"group.name\" class=\"card\">\n        <div class=\"mb-3 flex items-center justify-between\">\n          <h2 class=\"text-sm font-semibold text-slate-300\">{{ group.name }}</h2>\n          <span class=\"text-[11px] text-slate-600\">{{ group.items.length }} 个场景</span>\n        </div>\n        <div class=\"grid gap-2 sm:grid-cols-2 xl:grid-cols-3\">\n          <button v-for=\"s in group.items\" :key=\"s.key\" class=\"scenario\"\n                  :class=\"{ active: selectedKey === s.key }\"\n                  :title=\"'双击直接发送'\"\n                  @click=\"select(s)\" @dblclick=\"select(s); send()\">\n            <span class=\"text-xl leading-none\">{{ s.icon }}</span>\n            <span class=\"min-w-0\">\n              <span class=\"block truncate text-sm font-medium text-slate-200\">{{ s.label }}</span>\n              <span class=\"block text-[11px] leading-4 text-slate-500\">{{ s.desc }}</span>\n            </span>\n          </button>\n        </div>\n      </section>\n\n      <p class=\"px-1 text-[11px] text-slate-600\">\n        单击选中，双击直接发送；所有场景都用 .env 里的 device_key，参数可在右侧「手动微调 JSON」里改。\n        同一套场景也暴露给大模型：MCP 工具 <code class=\"text-amber-500/80\">bark_scenarios</code> / <code class=\"text-amber-500/80\">bark_scenario_push</code>。\n      </p>\n    </div>\n\n    <aside class=\"space-y-4\">\n      <section class=\"card\">\n        <div class=\"mb-3 flex items-center justify-between gap-2\">\n          <h2 class=\"text-sm font-semibold text-slate-300\">将发送</h2>\n          <span v-if=\"encrypt\" class=\"tagchip !text-amber-400\">加密 {{ algorithm }}/{{ mode }}</span>\n        </div>\n\n        <div class=\"rounded-xl border border-slate-800 bg-slate-900/80 p-3\">\n          <div class=\"flex gap-2.5\">\n            <div class=\"grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-amber-500 text-sm font-black text-slate-950\">B</div>\n            <div class=\"min-w-0 flex-1\">\n              <div class=\"text-[10px] uppercase tracking-wide text-slate-500\">Bark · 现在</div>\n              <div class=\"truncate text-sm font-semibold text-slate-100\">{{ preview.title || '（无标题）' }}</div>\n              <div class=\"truncate text-xs text-slate-400\" v-if=\"preview.subtitle\">{{ preview.subtitle }}</div>\n              <div class=\"clamp4 mt-0.5 whitespace-pre-wrap text-xs text-slate-300\">{{ preview.body || preview.markdown || '（无正文）' }}</div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"mt-3 flex flex-wrap gap-1.5\">\n          <span v-for=\"tag in previewTags\" :key=\"tag\" class=\"tagchip\">{{ tag }}</span>\n          <span v-if=\"!previewTags.length\" class=\"hint\">空 payload</span>\n        </div>\n\n        <details class=\"mt-3\">\n          <summary>手动微调 JSON（device_key / device_keys 等）</summary>\n          <textarea class=\"inp mt-2 font-mono text-xs\" rows=\"10\" v-model=\"draft\" spellcheck=\"false\"></textarea>\n          <div class=\"mt-2 flex flex-wrap items-center gap-2\">\n            <button class=\"btn btn-ghost\" @click=\"resetDraft\">恢复场景默认</button>\n            <span class=\"hint\">改完直接用顶部「发送」</span>\n          </div>\n          <p class=\"hint mt-2\">批量推送在 JSON 里加 <code class=\"text-amber-500/80\">\"device_keys\": [\"key1\",\"key2\"]</code>（自动忽略 device_key）。</p>\n        </details>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"mb-3 flex items-center justify-between gap-2\">\n          <h2 class=\"text-sm font-semibold text-slate-300\">发送结果</h2>\n          <span v-if=\"result && result.scenario\" class=\"tagchip\">{{ result.scenario }}</span>\n        </div>\n\n        <div v-if=\"!result\" class=\"rounded-xl border border-dashed border-slate-800 p-5 text-center text-xs text-slate-600\">\n          发送后显示 Bark 返回\n        </div>\n\n        <div v-else class=\"space-y-3\">\n          <div class=\"flex items-center gap-2 rounded-lg border px-3 py-2 text-xs\"\n               :class=\"result.ok ? 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400'\n                                 : 'border-rose-500/30 bg-rose-500/10 text-rose-400'\">\n            <span class=\"h-2 w-2 rounded-full\" :class=\"result.ok ? 'bg-emerald-400' : 'bg-rose-400'\"></span>\n            <span class=\"font-semibold\">{{ result.ok ? '发送成功' : '发送失败' }}</span>\n            <span class=\"ml-auto text-slate-400\">{{ result.encrypted ? result.algorithm + '/' + result.mode : '明文' }}</span>\n          </div>\n\n          <div v-if=\"result.error\" class=\"rounded-lg bg-rose-500/10 p-2 text-xs text-rose-300\">{{ result.error }}</div>\n\n          <details open>\n            <summary>Bark 返回</summary>\n            <pre class=\"rounded-lg bg-slate-950/80 p-3 text-slate-300\">{{ barkPretty }}</pre>\n          </details>\n          <details>\n            <summary>实际请求参数</summary>\n            <pre class=\"rounded-lg bg-slate-950/80 p-3 text-slate-300\">{{ requestPretty }}</pre>\n          </details>\n          <details v-if=\"result.ciphertext\">\n            <summary>密文与 IV</summary>\n            <pre class=\"rounded-lg bg-slate-950/80 p-3 text-slate-300\">iv: {{ result.iv || '（ECB 无 IV）' }}\n\nciphertext:\n{{ result.ciphertext }}</pre>\n          </details>\n          <details v-if=\"result.plain && Object.keys(result.plain).length\">\n            <summary>加密前内容</summary>\n            <pre class=\"rounded-lg bg-slate-950/80 p-3 text-slate-300\">{{ plainPretty }}</pre>\n          </details>\n        </div>\n      </section>\n    </aside>\n  </main>\n\n  <div v-if=\"keyDialog\" class=\"modal\" @click.self=\"keyDialog = false\">\n    <div class=\"card w-[min(92vw,26rem)]\">\n      <h2 class=\"text-sm font-semibold text-slate-200\">需要访问令牌</h2>\n      <p class=\"hint mt-1\">服务端配置了 BARK_KEY，含密钥的接口需要 <code>Authorization: Bearer &lt;BARK_KEY&gt;</code>。</p>\n      <input class=\"inp mt-3 font-mono text-xs\" v-model=\"tokenDraft\" placeholder=\"粘贴 BARK_KEY\" @keyup.enter=\"saveToken\">\n      <div class=\"mt-3 flex justify-end gap-2\">\n        <button class=\"btn btn-ghost\" @click=\"keyDialog = false\">取消</button>\n        <button class=\"btn btn-primary\" @click=\"saveToken\">保存并重试</button>\n      </div>\n    </div>\n  </div>\n\n  <div v-if=\"toast\" class=\"toast rounded-full px-4 py-2 text-xs font-semibold shadow-lg\"\n       :class=\"toastOk ? 'bg-emerald-500 text-slate-950' : 'bg-rose-500 text-white'\">\n    {{ toast }}\n  </div>\n</div>\n\n<script>\nconst { createApp } = Vue;\n\nconst TOKEN_STORAGE_KEY = 'bark.mcp.token';\n\nconst progressScenario = {\n  key: 'progress', icon: '📊', label: '进度更新', desc: '同 id 更新同一条',\n  dynamic: 'progress', payload: { title: '下载进度', body: '已完成 40%', id: 'demo-progress', isArchive: '1' }\n};\n\ncreateApp({\n  data() {\n    return {\n      cfg: { server: '', device_key_masked: '', keys: {}, algorithms: [], modes: [], scenarios: [], auth_required: false },\n      scenarioGroups: [],\n      selectedKey: '',\n      draft: '',\n      encrypt: false,\n      algorithm: 'aes-128',\n      mode: 'cbc',\n      progress: 40,\n      sending: false,\n      result: null,\n      toast: '',\n      toastOk: true,\n      keyDialog: false,\n      tokenDraft: '',\n      token: localStorage.getItem(TOKEN_STORAGE_KEY) || ''\n    };\n  },\n  computed: {\n    allScenarios() { return this.scenarioGroups.flatMap(g => g.items); },\n    selected() { return this.allScenarios.find(s => s.key === this.selectedKey) || null; },\n    currentKey() { return this.cfg.keys[this.algorithm] || ''; },\n    preview() {\n      try {\n        const value = JSON.parse(this.draft || '{}');\n        return value && typeof value === 'object' && !Array.isArray(value) ? value : {};\n      } catch (err) {\n        return this.selected ? this.selected.payload : {};\n      }\n    },\n    previewTags() {\n      const tags = Object.entries(this.preview).map(([key, value]) => {\n        const text = typeof value === 'string' ? value.replace(/\\s+/g, ' ') : JSON.stringify(value);\n        return key + ': ' + (text.length > 26 ? text.slice(0, 26) + '…' : text);\n      });\n      return tags.slice(0, 8);\n    },\n    barkPretty() { return this.stringify(this.result && this.result.bark); },\n    requestPretty() { return this.stringify(this.result && this.result.request); },\n    plainPretty() { return this.stringify(this.result && this.result.plain); }\n  },\n  created() {\n    this.loadConfig();\n  },\n  methods: {\n    headers(extra) {\n      const headers = Object.assign({}, extra || {});\n      if (this.token) headers.Authorization = 'Bearer ' + this.token;\n      return headers;\n    },\n    async api(path, init) {\n      const options = Object.assign({}, init || {});\n      options.headers = this.headers(options.headers);\n      const res = await fetch(path, options);\n      if (res.status === 401) {\n        this.openKeyDialog();\n        throw new Error('需要 BARK_KEY 认证');\n      }\n      return res;\n    },\n    openKeyDialog() {\n      this.tokenDraft = this.token;\n      this.keyDialog = true;\n    },\n    saveToken() {\n      this.token = this.tokenDraft.trim();\n      if (this.token) localStorage.setItem(TOKEN_STORAGE_KEY, this.token);\n      else localStorage.removeItem(TOKEN_STORAGE_KEY);\n      this.keyDialog = false;\n      this.loadConfig();\n    },\n    select(scenario) {\n      if (!scenario) return;\n      this.selectedKey = scenario.key;\n      if (scenario.encrypt) this.encrypt = true;\n      this.draft = JSON.stringify(scenario.payload, null, 2);\n    },\n    resetDraft() {\n      if (this.selected) this.draft = JSON.stringify(this.selected.payload, null, 2);\n    },\n    stringify(value) {\n      if (value === undefined || value === null) return '—';\n      return typeof value === 'string' ? value : JSON.stringify(value, null, 2);\n    },\n    showToast(message, ok = true) {\n      this.toast = message;\n      this.toastOk = ok;\n      clearTimeout(this._toastTimer);\n      this._toastTimer = setTimeout(() => { this.toast = ''; }, 2600);\n    },\n    async loadConfig() {\n      try {\n        const res = await this.api('/api/config');\n        if (!res.ok) throw new Error('HTTP ' + res.status);\n        const data = await res.json();\n        this.cfg = data;\n        const groups = Array.isArray(data.scenarios) && data.scenarios.length ? data.scenarios : [];\n        // 进度场景在服务端是静态 payload，这里换成会自增的本地版本\n        this.scenarioGroups = groups.map(group => ({\n          ...group,\n          items: group.items.map(item => item.key === 'progress' ? { ...item, dynamic: 'progress' } : item)\n        }));\n        if (!this.selectedKey && this.allScenarios.length) this.select(this.allScenarios[0]);\n        if (this.algorithm && !(this.cfg.keys || {})[this.algorithm]) {\n          this.algorithm = (this.cfg.algorithms && this.cfg.algorithms[0]) || 'aes-128';\n        }\n      } catch (err) {\n        if (String(err.message).includes('BARK_KEY')) return;\n        this.showToast('后端配置加载失败：' + err.message, false);\n      }\n    },\n    async copy(text, label) {\n      if (!text) return;\n      try {\n        await navigator.clipboard.writeText(text);\n        this.showToast((label || '内容') + '已复制');\n      } catch (err) {\n        this.showToast('复制失败，请手动选择', false);\n      }\n    },\n    async regenerate() {\n      try {\n        const res = await this.api('/api/crypto/regenerate', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ algorithm: this.algorithm })\n        });\n        const data = await res.json();\n        if (!data.ok) throw new Error(data.error || 'HTTP ' + res.status);\n        this.cfg.keys[data.algorithm] = data.key;\n        this.showToast('已生成新密钥，记得同步更新 App');\n      } catch (err) {\n        this.showToast('生成失败：' + err.message, false);\n      }\n    },\n    async send() {\n      if (this.sending || !this.selected) return;\n\n      let payload;\n      try {\n        payload = JSON.parse(this.draft);\n        if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {\n          throw new Error('根节点必须是 JSON 对象');\n        }\n      } catch (err) {\n        this.result = { ok: false, error: 'JSON 解析失败：' + err.message, scenario: this.selected.label };\n        this.showToast('JSON 格式错误', false);\n        return;\n      }\n\n      if (this.selected.dynamic === 'progress') {\n        this.progress = this.progress >= 100 ? 20 : this.progress + 20;\n        payload = { ...payload, body: '已完成 ' + this.progress + '%' };\n        this.draft = JSON.stringify(payload, null, 2);\n      }\n\n      this.sending = true;\n      try {\n        const res = await this.api('/api/push', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ ...payload, encrypt: this.encrypt, algorithm: this.algorithm, mode: this.mode })\n        });\n        const data = await res.json();\n        this.result = { ...data, scenario: this.selected.label };\n        const message = data.error || (data.bark && data.bark.message) || ('HTTP ' + res.status);\n        this.showToast(data.ok ? '已发送 · ' + this.selected.label : '发送失败：' + message, !!data.ok);\n      } catch (err) {\n        this.result = { ok: false, error: String(err.message || err), scenario: this.selected.label };\n        this.showToast('发送失败：' + (err.message || err), false);\n      } finally {\n        this.sending = false;\n      }\n    }\n  }\n}).mount('#app');\n</script>\n</body>\n</html>\n";
